using C__Classes;
using UnityEngine;

namespace Enemy.Scripts
{
    public class EnemyProjectile : MonoBehaviour
    {
        private float damage;
        private float speed;
        private Vector3 targetPos;
        private Vector3 direction; // If moving linearly
        private bool isHoming = false; // Could extend later if needed

        // Initialize projectile
        public void Setup(float dmg, float spd)
        {
            damage = dmg;
            speed = spd;

            // Fix rendering issues
            // Use GetComponentInChildren to find the renderer even if it's on a child object
            var sr = GetComponentInChildren<SpriteRenderer>();
            if (sr != null)
            {
                // "Foreground" is defined in ProjectSettings/TagManager.asset as the top-most layer
                sr.sortingLayerName = "Foreground";
                sr.sortingOrder = 50; 
            }

            // Fix Z position to be safe (ensure it's not behind the background)
            Vector3 pos = transform.position;
            pos.z = 0f; 
            transform.position = pos;

            // Destroy after 5 seconds to prevent memory leaks
            Destroy(gameObject, 5f);
        }

        private void Update()
        {
            // Move forward relative to rotation (assuming prefab is oriented right/forward)
            // If the sprite points right, use Vector3.right. If up, use Vector3.up.
            // Standard in 2D is often Right.
            transform.Translate(Vector3.right * speed * Time.deltaTime);
        }

        private void OnTriggerEnter2D(Collider2D other)
        {
            // Ignore other enemies (Tag check if exists, otherwise Component check)
            if (other.GetComponent<NpcBase>() != null)
            {
                return;
            }

            // Hit Player?
            // Check both common cases for Player tag
            if (other.CompareTag("Player") || other.CompareTag("player")) 
            {
                Actor actor = other.GetComponent<Actor>();
                if (actor != null)
                {
                    actor.DealDamage(damage);
                    Destroy(gameObject);
                }
            }
            // Hit Obstacle? (Ground layer usually, or just any non-trigger static collider)
            // We can check if it's NOT the player, NOT an enemy, and NOT a trigger.
            // Also ignore other projectiles
            else if (!other.isTrigger && !other.CompareTag("projectile") && !other.CompareTag("heal"))
            {
                 // Simple wall detection: If it's not a character, destroy.
                 // Ideally we'd check LayerMask, but names are uncertain.
                 // Assuming "Ground" layer exists based on Projectile.cs
                 if(other.gameObject.layer == LayerMask.NameToLayer("Ground") || other.gameObject.layer == 0) // Default layer
                 {
                     Destroy(gameObject);
                 }
            }
        }
    }
}

using System.Collections.Generic;
using System.Numerics;
using C__Classes;
using Unity.VisualScripting;
using UnityEngine;
using UnityEngine.AI;
using Vector2 = UnityEngine.Vector2;
using Vector3 = UnityEngine.Vector3;

namespace Enemy.Scripts
{
    public class NpcBase : Actor
    {
        protected NavMeshAgent agent;
        private Transform playerTarget;
        private float pathUpdateTimer = 0f;
        private const float PATH_UPDATE_DELAY = 0.5f;
        public enum State { Asleep, Aggravated}
        private State currentState = State.Asleep;

        private float _lastKnownHealth;

        //for animation timing (so it doesn't loop)
        private float lastHurtTime = -1f;
        [SerializeField] private float hurtAnimCooldown = 0.5f; 

        // private Actor actor;

        //Animation stuff
        private Animator animator;

        new void Start()
        {
            base.Start();
            print(this.gameObject.name);
            // actor = GetComponent<Actor>();
            agent = GetComponent<NavMeshAgent>();
            print(agent);
            agent.updateRotation = false;
            agent.updateUpAxis = false;
            agent.speed = speed;
            animator = GetComponent<Animator>();

            _lastKnownHealth = currentHealth;

            // PAMIĘTAJ: Jeśli w base.Start() masz jakieś dzielenie speed /= 50, 
            // to AI będzie bardzo wolne. Przy delcie operujemy na czystych wartościach.
        }
        new void Update()
        {
            base.Update();

            CheckForHurtAnimation();

            if (isDead)
            {
                return;
            }

            switch (currentState)
            {
                case State.Aggravated:
                    MoveToTarget();
                    break;
                case State.Asleep:
                    // [W] opcjonalny patrol?
                    break;
            }
            FixZPosition();
            UpdateAnimation();
        }

        private void CheckForHurtAnimation()
        {
            if (!(Mathf.Abs(currentHealth - _lastKnownHealth) > 0.01f))
            {
                return;
            }

            //We check if the health is lower than last known health so we can play hurt or death animation
            if (!(currentHealth < _lastKnownHealth))
            {
                return;
            }

            if (currentHealth <= 0)
            {
                animator.SetTrigger("Die");
            }
            else
            {
                //Added so the animation doesn't loop
                if (!(Time.time >= lastHurtTime + hurtAnimCooldown))
                {
                    return;
                }

                animator.SetTrigger("Hurt");
                lastHurtTime = Time.time;
            }

            _lastKnownHealth = currentHealth;
        }

        private new void DealDamage(float dmg)
        {
            base.DealDamage(dmg);
        }

        void MoveToTarget()
        {
            if (!playerTarget) return;

            pathUpdateTimer += Time.deltaTime;
            if (pathUpdateTimer >= PATH_UPDATE_DELAY)
            {
                agent.SetDestination(playerTarget.position);
                pathUpdateTimer = 0f;
            }
        }

        void FixZPosition()
        {
            if (Mathf.Abs(transform.position.z) > 0.01f)
            {
                Vector3 pos = transform.position;
                pos.z = 0;
                transform.position = pos;
            }
        }



        void UpdateAnimation()
        {
            bool isMoving = Mathf.Abs(agent.velocity.x) > 0.01f || Mathf.Abs(agent.velocity.y) > 0.01f;
            animator.SetBool("isWalking", isMoving);

            if (V3toV2(agent.velocity) != Vector2.zero)
            {
                if(agent.velocity.x < 0)
                    animator.SetFloat("XInput", -1); 
                else 
                    animator.SetFloat("XInput", agent.velocity.x); // Tu warto by dać Mathf.Sign lub 1, żeby animacja się nie psuła przy małych prędkościach
                animator.SetFloat("YInput", agent.velocity.y);    
            }
        }

        private Vector2 V3toV2(Vector3 v)
        {
            return new Vector2(v.x, v.y);
        }

        public void Aggravate(Transform target)
        {
            playerTarget = target;
            currentState = State.Aggravated;
            pathUpdateTimer = PATH_UPDATE_DELAY;
        }

        public void Pacify()
        {
            playerTarget = null;
            currentState = State.Asleep;
        }
    }
}

