using C__Classes;
using Enemy.Scripts;
using UnityEngine;

namespace Enemy.Scripts
{
    public class RangerEnemy : NpcBase
    {
        [Header("Ranger Combat Stats")]
        [SerializeField] private GameObject projectilePrefab;
        [SerializeField] private float projectileSpeed = 10f;
        [SerializeField] private float projectileDamage = 10f; // Can be different from contact damage (which is 0)
        [SerializeField] private float fireRate = 1.5f; // Seconds between shots
        [SerializeField] private float attackRange = 10f;

        [Header("Ranger Movement")]
        [SerializeField] private float idealDistance = 6f; // Try to keep this distance
        [SerializeField] private float distanceBuffer = 1f; // Don't jitter movement if within ideal +/- buffer

        private float _fireCooldown = 0f;

        protected override void Start()
        {
            // Set contact damage to 0 as requested
            damage = 0f;
            base.Start();
        }

        protected override void Update()
        {
            // Handles animation, state machine, etc.
            base.Update();

            // Handle shooting cooldown here (so it ticks down regardless of state)
             if (_fireCooldown > 0)
            {
                _fireCooldown -= Time.deltaTime;
            }
        }

        protected override void MoveToTarget()
        {
            if (playerTarget == null) return;

            float dist = Vector3.Distance(transform.position, playerTarget.position);

            // Update movement less frequently, unless running away (needs responsiveness)
            // But we must tick the timer
            pathUpdateTimer += Time.deltaTime;

            // Calculate direction AWAY from player
            Vector3 runDir = (transform.position - playerTarget.position).normalized;

            // Too Close: Run away (Responsive)
            if (dist < idealDistance - distanceBuffer)
            {
                if (pathUpdateTimer >= 0.1f) // Faster updates for kiting
                {
                    Vector3 dest = transform.position + runDir * 3.0f; // Run 3 units away
                    agent.SetDestination(dest);
                    pathUpdateTimer = 0f;
                }
            }
            // Too Far: Chase to ideal distance (Standard Delay)
            else if (dist > idealDistance + distanceBuffer)
            {
                if (pathUpdateTimer >= PATH_UPDATE_DELAY)
                {
                    agent.SetDestination(playerTarget.position);
                    pathUpdateTimer = 0f;
                }
            }
            // Sweet spot: Stop
            else
            {
                if (pathUpdateTimer >= 0.2f)
                {
                    agent.ResetPath(); // Stop moving
                    pathUpdateTimer = 0f;
                }
            }

            // SHOOT LOGIC
            // Check if can shoot
            if (_fireCooldown <= 0 && dist <= attackRange)
            {
                // Check Line of Sight (optional but simplified: just shoot towards player)
                // Calculate direction TO player
                Vector3 shootDir = (playerTarget.position - transform.position).normalized;
                Shoot(shootDir);
                _fireCooldown = fireRate;
            }
        }

        private void Shoot(Vector3 direction)
        {
            if (projectilePrefab == null) return;

            float angle = Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg;
            Quaternion rotation = Quaternion.Euler(0, 0, angle);

            GameObject proj = Instantiate(projectilePrefab, transform.position, rotation);
            EnemyProjectile ep = proj.GetComponent<EnemyProjectile>();
            if (ep != null)
            {
                ep.Setup(projectileDamage, projectileSpeed);
            }
        }

        private void OnDrawGizmosSelected()
        {
            Gizmos.color = Color.red;
            Gizmos.DrawWireSphere(transform.position, attackRange);
            Gizmos.color = Color.green;
            Gizmos.DrawWireSphere(transform.position, idealDistance);
        }
    }
}

using System.Collections.Generic;
using UnityEngine;
using Enemy.Scripts;

namespace Enemy.Scripts
{
    public class StalkerEnemy : NpcBase
    {
        [Header("Stalker Settings")]
        [SerializeField] private float warningRadius = 15f;
        [SerializeField] private float alertFrequency = 1.0f;
        [SerializeField] private float stalkingSpeed = 2f;

        private float _alertTimer = 0f;

        // Ensure we don't attack
        protected override void Start()
        {
            // Call NpcBase Start
            base.Start();

            // Stalker specific stats
            damage = 0f; 
            agent.speed = stalkingSpeed; 
        }

        protected override void Update()
        {
            // Call NpcBase Update (handles movement, animation, hurt logic)
            base.Update();

            // Only alert if we are aggravated (Player is in FOV)
            if (currentState == State.Aggravated && playerTarget != null)
            {
                HandleAlertPulse();

                // Ensure speed is maintained (in case something resets it)
                agent.speed = stalkingSpeed;
            }
        }

        private void HandleAlertPulse()
        {
            _alertTimer += Time.deltaTime;
            if (_alertTimer >= alertFrequency)
            {
                _alertTimer = 0f;
                AlertNearbyZombies();
            }
        }

        private void AlertNearbyZombies()
        {
            // Find all colliders in warning radius
            // We assume zombies are on a layer that default Physics queries hit, 
            // or we could specify a layer mask if known. 
            // For now, we'll hit all triggers/colliders and filter by component.

            Collider2D[] hits = Physics2D.OverlapCircleAll(transform.position, warningRadius);

            foreach (var hit in hits)
            {
                // Don't alert self
                if (hit.gameObject == gameObject) continue;

                // Check if it's an NpcBase (covers normal zombies and BlindEnemy)
                NpcBase npc = hit.GetComponent<NpcBase>();
                if (npc != null)
                {
                    // Don't re-alert other Stalkers if we don't want a chain reaction loop 
                    // (though requirement says "Alert zombies", implies all).
                    // We simply pass the player target.
                    npc.Aggravate(playerTarget);
                }
            }
        }

        // Debug visualization for warning radius
        private void OnDrawGizmosSelected()
        {
            Gizmos.color = Color.yellow;
            Gizmos.DrawWireSphere(transform.position, warningRadius);
        }
    }
}
